def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Repeated isolated cells are copy-location markers.
    isolated = Counter()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if all(not (0 <= r+dr < h and 0 <= c+dc < w)
                   or grid[r+dr][c+dc] in (bg, v)
                   for dr, dc in ((1,0),(-1,0),(0,1),(0,-1))):
                # Require no neighboring non-background cell of any color.
                if all(not (0 <= r+dr < h and 0 <= c+dc < w)
                       or grid[r+dr][c+dc] == bg
                       for dr, dc in ((1,0),(-1,0),(0,1),(0,-1))):
                    isolated[v] += 1
    marker = max(isolated, key=lambda v: isolated[v])
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    cells = [(r,c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    ph, pw = r1-r0+1, c1-c0+1
    pattern = [(r-r0, c-c0, grid[r][c]) for r,c in cells]

    out = [row[:] for row in grid]
    for r,c in markers:
        out[r][c] = bg
    for r,c in markers:
        for dr,dc,v in pattern:
            rr, cc = r + dr - ph//2, c + dc - pw//2
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out
